select t1.id as id, t1.material_code as materialCode, t3.site_name as stackName, t1.maintence_style as maintenceStyle, t2.phases as phases, t2.id as stageId, t2.aftercare_date_end as aftercareDateEnd from tb_maintain_plan t1 left join tb_maintain_plan_stage t2 on t1.stage_id = t2.id inner join (select id,site_name from tb_stack site_name like concat('%',#{maintainPlanDto.stackName},'%') ) t3 on t3.id = t1.stack_id
t1.is_end = '0' and t2.aftercare_date_end <= #{maintainPlanDto.nowDate} and t2.is_change = '0'
and t1.material_code like concat('%',#{maintainPlanDto.materialCode},'%')
and t2.created_time >= #{maintainPlanDto.startTime}
and t2.created_time <= #{maintainPlanDto.endTime}
and t2.maintain_count = #{maintainPlanDto.maintainCount}
and t2.phases = #{maintainPlanDto.phases}
and t1.maintence_style = #{maintainPlanDto.maintenceStyle}
order by created_time desc

SELECT material_code as materialCode FROM tb_maintain_count
WHERE 1=1
 and material_code like concat('%',#{maintainCountDto.materialCode},'%')
 and maintence_style = #{maintainCountDto.maintenceStyle}
 and phases = #{maintainCountDto.phases}
 and created_time >= #{maintainCountDto.startTime}
 and created_time <= #{maintainCountDto.endTime}
GROUP BY material_code

SELECT t.material_code as materialCode,substring_index(t.pid_route,',',3) as pidRoute,SUM(t.maintain_count) as maintainCount,a.site_name as stackName FROM tb_maintain_count t
    inner join tb_building a on a.id = substring_index(substring_index(t.pid_route,'03:',-1),']',1)
WHERE 1=1
 and t.material_code = #{maintainCountDto.materialCode}
 and t.maintence_style = #{maintainCountDto.maintenceStyle}
 and t.phases = #{maintainCountDto.phases}
 and t.created_time >= #{maintainCountDto.startTime}
 and t.created_time <= #{maintainCountDto.endTime}
GROUP BY t.material_code,substring_index(t.pid_route,',',3),a.site_name

SELECT t.material_code as materialCode,t.p as pidRoute,t.maintain_count as maintainCount,t.site_name as stackName FROM (
SELECT t3.* FROM (
SELECT f1.material_code,substring_index(f1.pid_route,',',4) p,SUM(f1.maintain_count) as maintain_count,a1.site_name FROM tb_maintain_count f1
inner join tb_floor a1 on a1.id = substring_index(substring_index(f1.pid_route,'04:',-1),']',1)
WHERE 1=1
 and f1.material_code = #{maintainCountDto.materialCode}
 and f1.pid_route like concat('%',#{maintainCountDto.pidRoute},'%')
 and f1.maintence_style = #{maintainCountDto.maintenceStyle}
 and f1.phases = #{maintainCountDto.phases}
 and f1.created_time >= #{maintainCountDto.startTime}
 and f1.created_time <= #{maintainCountDto.endTime}
GROUP BY f1.material_code,substring_index(f1.pid_route,',',4),a1.site_name) t3
UNION
SELECT t4.* FROM (
SELECT f2.material_code,substring_index(f2.pid_route,',',5) p,SUM(f2.maintain_count) as maintain_count,a2.site_name FROM tb_maintain_count f2
inner join tb_ware_area a2 on a2.id = substring_index(substring_index(f2.pid_route,'05:',-1),']',1)
WHERE 1=1
 and f2.material_code = #{maintainCountDto.materialCode}
 and f2.pid_route like concat('%',#{maintainCountDto.pidRoute},'%')
 and f2.maintence_style = #{maintainCountDto.maintenceStyle}
 and f2.phases = #{maintainCountDto.phases}
 and f2.created_time >= #{maintainCountDto.startTime}
 and f2.created_time <= #{maintainCountDto.endTime}
GROUP BY f2.material_code,substring_index(f2.pid_route,',',5),a2.site_name) t4
UNION
SELECT t5.* FROM (
SELECT f3.material_code,substring_index(f3.pid_route,',',6) p,SUM(f3.maintain_count) as maintain_count,a3.site_name FROM tb_maintain_count f3
inner join tb_stack a3 on a3.id = substring_index(substring_index(f3.pid_route,'05:',-1),']',1)
WHERE 1=1
 and f3.material_code = #{maintainCountDto.materialCode}
 and f3.pid_route like concat('%',#{maintainCountDto.pidRoute},'%')
 and f3.maintence_style = #{maintainCountDto.maintenceStyle}
 and f3.phases = #{maintainCountDto.phases}
 and f3.created_time >= #{maintainCountDto.startTime}
 and f3.created_time <= #{maintainCountDto.endTime}
GROUP BY f3.material_code,substring_index(f3.pid_route,',',6),a3.site_name) t5) t ORDER BY t.material_code,t.p

select sum(maintain_count) from tb_maintain_count
WHERE 1=1
 and material_code like concat('%',#{maintainCountDto.materialCode},'%')
 and pid_route like concat('%',#{maintainCountDto.pidRoute},'%')
 and maintence_style = #{maintainCountDto.maintenceStyle}
 and phases = #{maintainCountDto.phases}
 and created_time >= #{maintainCountDto.startTime}
 and created_time <= #{maintainCountDto.endTime}
